S_GIT = S("Git-Dokumentation und Pro Git (S. Chacon, B. Straub)", "https://git-scm.com/book/de/v2")
S_SEMVER = S("Semantic Versioning 2.0.0", "https://semver.org/lang/de/")
S_DOCKER = S("Docker-Dokumentation", "https://docs.docker.com/")
S_K8S = S("Kubernetes-Dokumentation", "https://kubernetes.io/de/docs/home/")
S_TF = S("Terraform-Dokumentation (HashiCorp) und OpenTofu", "https://developer.hashicorp.com/terraform/docs")
S_GITOPS = S("OpenGitOps: GitOps-Prinzipien (CNCF)", "https://opengitops.dev/")
S_SRE = S("Google: Site Reliability Engineering (Bücher frei online)", "https://sre.google/books/")
S_OTEL = S("OpenTelemetry-Dokumentation", "https://opentelemetry.io/docs/")
S_SLSA = S("SLSA: Supply-chain Levels for Software Artifacts", "https://slsa.dev/")
S_OWASP = S("OWASP: Projekte zu Anwendungssicherheit (u. a. Top 10, DevSecOps)", "https://owasp.org/")
S_ASPICE = S("VDA QMC: Automotive SPICE (Prozessbewertungsmodell)", "https://vda-qmc.de/automotive-spice/")
