M1 = M("devops.m1", 1, "Was DevOps wirklich ist", "Kultur, Prinzipien, Wertstrom und die Kennzahlen, an denen man gute Teams erkennt.", [
 L("devops.m1.l1", "Die Mauer zwischen Dev und Ops", 5, [
  "Früher arbeiteten Entwicklung (Dev) und Betrieb (Ops) getrennt. Entwickler wollten schnell Neues liefern, der Betrieb wollte Stabilität. Software wurde „über die Mauer geworfen“: selten, in großen Paketen, mit langen Nächten bei jedem Release.",
  "## Die Idee",
  "DevOps verbindet beides: Teams verantworten ihre Software von der Idee bis zum Betrieb („you build it, you run it“). Ziel ist, Änderungen schnell, sicher und häufig auszuliefern. Der Begriff entstand um 2009, unter anderem durch die erste DevOpsDays-Konferenz von Patrick Debois in Gent.",
  "## Was DevOps nicht ist",
  "DevOps ist kein Werkzeug, keine Stellenbezeichnung und keine eigene Abteilung zwischen Dev und Ops. Wer nur Werkzeuge kauft, aber Silos und Übergaben behält, hat kein DevOps. Es ist vor allem eine Arbeitsweise und Kultur, unterstützt durch Automatisierung."],
  ["Früher: Silos, seltene große Releases, Übergaben.", "DevOps: gemeinsame Verantwortung von Idee bis Betrieb.", "Kultur und Arbeitsweise, nicht Werkzeug oder Abteilung."],
  [S_DOH, S_ACC],
  [card("DevOps", "Arbeitsweise und Kultur, die Entwicklung und Betrieb verbindet, um schnell und sicher zu liefern."), card("You build it, you run it", "Das Team, das Software baut, betreibt sie auch."), card("Silo", "Abgeschottete Abteilung mit eigenen Zielen und Übergaben an andere.")],
  [mc("Was ist DevOps im Kern?", ["Kultur und Arbeitsweise", "Ein bestimmtes Werkzeug", "Eine neue Abteilung", "Eine Programmiersprache"], "Werkzeuge unterstützen, ersetzen die Kultur aber nicht."),
   mc("Was bedeutet „you build it, you run it“?", ["Das Team betreibt seine Software selbst", "Jeder baut sein eigenes Auto", "Ops schreibt den Code", "Tests laufen nur nachts"], "Verantwortung endet nicht beim Commit."),
   mc("Was war typisch vor DevOps?", ["Seltene, große Releases", "Tägliche kleine Releases", "Keine Tests", "Keine Server"], "Mit hohem Risiko pro Release."),
   mc("Wann entstand der Begriff DevOps etwa?", ["Um 2009", "Um 1970", "Um 1995", "Um 2020"], "DevOpsDays in Gent 2009."),
   mc("Was ist kein DevOps?", ["Eine DevOps-Abteilung zwischen Silos", "Gemeinsame Verantwortung", "Automatisierte Auslieferung", "Schnelles Feedback"], "Das wäre nur ein weiteres Silo.")]),
 L("devops.m1.l2", "CALMS und die drei Wege", 6, [
  "Zwei Modelle helfen, DevOps zu verstehen.",
  "## CALMS",
  "Culture (Zusammenarbeit, Vertrauen, Lernen aus Fehlern), Automation (alles Wiederholbare automatisieren), Lean (kleine Schritte, Verschwendung vermeiden, Fluss), Measurement (messen statt raten) und Sharing (Wissen und Verantwortung teilen).",
  "## Die drei Wege",
  "Aus dem DevOps Handbook: Erstens Flow, also schneller Fluss von der Idee bis zum Kunden durch kleine Pakete und wenig Wartezeit. Zweitens Feedback, also schnelle Rückmeldung aus Tests, Betrieb und Nutzung. Drittens kontinuierliches Lernen und Experimentieren, auch aus Fehlern.",
  "## Wertstrom",
  "Wertstromanalyse (Value Stream Mapping) zeigt, wo Zeit verloren geht. Oft wird nur ein kleiner Teil der Durchlaufzeit wirklich gearbeitet; der Rest ist Warten auf Freigaben, Tests oder Umgebungen."],
  ["CALMS: Culture, Automation, Lean, Measurement, Sharing.", "Drei Wege: Flow, Feedback, Lernen.", "Wertstromanalyse findet Wartezeiten."],
  [S_DOH],
  [card("CALMS", "Culture, Automation, Lean, Measurement, Sharing: Säulen von DevOps."), card("Wertstromanalyse", "Darstellung aller Schritte von Idee bis Kunde, um Wartezeiten zu finden."), card("Durchlaufzeit", "Zeit von Beginn bis Auslieferung einer Änderung.")],
  [mc("Wofür steht das L in CALMS?", ["Lean", "Linux", "Logging", "Load"], "Kleine Schritte, Fluss, Verschwendung vermeiden."),
   order("Ordne die drei Wege.", ["Flow", "Feedback", "Kontinuierliches Lernen"], "Fluss, Rückmeldung, Lernen."),
   mc("Was zeigt eine Wertstromanalyse oft?", ["Viel Wartezeit", "Zu wenig Server", "Zu viele Tests", "Zu schnelle Releases"], "Arbeitszeit ist oft nur ein kleiner Teil."),
   mc("Was meint der erste Weg?", ["Schneller Fluss zum Kunden", "Mehr Meetings", "Längere Releases", "Mehr Dokumente"], "Kleine Pakete, wenig Warten."),
   mc("Was meint Measurement?", ["Messen statt raten", "Server wiegen", "Code zählen", "Arbeitszeit kontrollieren"], "Entscheidungen auf Daten stützen.")]),
 L("devops.m1.l3", "Die DORA-Kennzahlen", 7, [
  "Das Forschungsprogramm DORA hat über Jahre tausende Teams befragt. Ergebnis (beschrieben im Buch „Accelerate“): Vier Kennzahlen unterscheiden leistungsstarke von schwachen Teams.",
  "## Die vier Schlüssel",
  "Deployment-Frequenz (wie oft wird ausgeliefert), Lead Time for Changes (Zeit vom Commit bis Produktion), Change Failure Rate (Anteil der Auslieferungen, die Probleme verursachen) und Time to Restore (wie schnell ein Ausfall behoben ist).",
  "## Die überraschende Erkenntnis",
  "Geschwindigkeit und Stabilität sind kein Widerspruch. Die besten Teams liefern häufig und haben gleichzeitig weniger Fehler und schnellere Wiederherstellung. Kleine Änderungen sind leichter zu prüfen und zurückzunehmen.",
  "## Vorsicht",
  "Kennzahlen dienen dem Lernen, nicht der Bewertung einzelner Menschen. Werden sie zu Zielen gemacht, werden sie manipuliert (Goodharts Gesetz)."],
  ["DORA: Deployment-Frequenz, Lead Time, Change Failure Rate, Time to Restore.", "Tempo und Stabilität gehen zusammen.", "Kennzahlen zum Lernen, nicht zur Personenbewertung."],
  [S_DORA, S_ACC],
  [card("Lead Time for Changes", "Zeit vom Commit bis zur Änderung in Produktion."), card("Change Failure Rate", "Anteil der Auslieferungen, die zu Fehlern oder Rücknahmen führen."), card("Time to Restore", "Zeit bis zur Wiederherstellung nach einem Ausfall."), card("Goodharts Gesetz", "Wird eine Kennzahl zum Ziel, hört sie auf, eine gute Kennzahl zu sein.")],
  [multi("Welche gehören zu den vier DORA-Kennzahlen?", ["Deployment-Frequenz", "Lead Time for Changes", "Change Failure Rate", "Anzahl Codezeilen"], [0, 1, 2], "Die vierte ist Time to Restore."),
   mc("Was fanden die DORA-Studien?", ["Tempo und Stabilität gehen zusammen", "Schnell heißt instabil", "Langsam ist immer sicher", "Nur große Firmen sind gut"], "Kleine Änderungen sind sicherer."),
   num("Von 40 Deployments führten 6 zu Problemen. Wie hoch ist die Change Failure Rate in Prozent?", 15, "%", 0.1, "6 ÷ 40 = 0,15."),
   mc("Wofür sollte man DORA-Kennzahlen nicht nutzen?", ["Bewertung einzelner Personen", "Verbesserungen erkennen", "Trends beobachten", "Engpässe finden"], "Sonst werden sie manipuliert."),
   mc("Was misst Lead Time for Changes?", ["Commit bis Produktion", "Idee bis Meeting", "Urlaub bis Rückkehr", "Bug bis Ticket"], "Wie schnell eine fertige Änderung beim Kunden ist.")])
])

M2 = M("devops.m2", 1, "Versionskontrolle mit Git", "Commits, Branches, Zusammenarbeit über Pull Requests und Branching-Strategien.", [
 L("devops.m2.l1", "Git-Grundlagen", 6, [
  "Versionskontrolle ist das Fundament von DevOps: Alles, was das System ausmacht, liegt versioniert in einem Repository, nicht nur Code, auch Konfiguration, Infrastruktur und Pipelines.",
  "## Git",
  "Git wurde 2005 von Linus Torvalds für den Linux-Kernel entwickelt. Es ist verteilt: Jede Kopie (Clone) enthält die vollständige Historie.",
  "## Die wichtigsten Begriffe",
  "Ein Commit ist ein Schnappschuss mit Autor, Zeit, Nachricht und Verweis auf den Vorgänger, eindeutig über einen Hash benannt. Die Staging Area sammelt Änderungen für den nächsten Commit (git add). Ein Branch ist ein beweglicher Zeiger auf einen Commit. Push und Pull gleichen mit einem entfernten Repository (Remote) ab.",
  "## Gute Commits",
  "Klein, in sich geschlossen, mit einer Nachricht, die erklärt, warum etwas geändert wurde. So lässt sich die Historie lesen, Fehler eingrenzen (git bisect) und Änderungen gezielt zurücknehmen (git revert)."],
  ["Alles versionieren: Code, Konfiguration, Infrastruktur, Pipelines.", "Git: verteilt, Commits mit Hash, Branches als Zeiger.", "Kleine Commits mit „Warum“-Nachricht."],
  [S_GIT],
  [card("Commit", "Versionierter Schnappschuss mit Hash, Autor, Zeit und Nachricht."), card("Branch", "Beweglicher Zeiger auf einen Commit; Entwicklungszweig."), card("git revert", "Erzeugt einen neuen Commit, der einen früheren rückgängig macht."), card("git bisect", "Binäre Suche in der Historie nach dem Commit, der einen Fehler einführte.")],
  [mc("Was ist ein Branch in Git?", ["Ein beweglicher Zeiger auf einen Commit", "Eine Kopie aller Dateien", "Ein Server", "Ein Backup auf Band"], "Deshalb sind Branches billig."),
   mc("Was macht git revert?", ["Neuer Commit, der einen alten aufhebt", "Löscht die Historie", "Lädt Code herunter", "Erstellt einen Branch"], "Die Historie bleibt erhalten."),
   mc("Was bedeutet „verteilt“ bei Git?", ["Jeder Clone hat die volle Historie", "Code liegt nur auf einem Server", "Dateien werden zufällig verteilt", "Nur ein Nutzer zur Zeit"], "Arbeiten auch offline möglich."),
   mc("Wozu dient git bisect?", ["Fehler einführenden Commit finden", "Branches zusammenführen", "Passwörter speichern", "Server starten"], "Binäre Suche."),
   mc("Was gehört in eine gute Commit-Nachricht?", ["Warum geändert wurde", "Das Wetter", "Nur „fix“", "Der komplette Code"], "Das Was zeigt der Diff.")]),
 L("devops.m2.l2", "Zusammenarbeit: Pull Requests und Reviews", 6, [
  "In Teams wird Code meist über Pull Requests (bei GitLab Merge Requests) zusammengeführt.",
  "## Ablauf",
  "Eine Entwicklerin erstellt einen Branch, committet, pusht und öffnet einen Pull Request. Automatische Prüfungen laufen (Build, Tests, Analyse), Kolleginnen und Kollegen prüfen den Code (Review). Nach Freigabe wird zusammengeführt (Merge).",
  "## Gute Reviews",
  "Kleine Pull Requests werden schneller und gründlicher geprüft. Reviews prüfen Verständlichkeit, Korrektheit, Tests und Risiken, nicht Formatierung (das erledigen Werkzeuge). Ton: freundlich, konkret, auf den Code bezogen, nicht auf die Person.",
  "## Merge-Varianten",
  "Merge-Commit behält die Verzweigung sichtbar. Squash fasst alle Commits zu einem zusammen. Rebase setzt Commits auf den neuesten Stand und erzeugt eine gerade Historie. Teams legen eine Variante fest."],
  ["Branch → Pull Request → automatische Prüfungen → Review → Merge.", "Kleine PRs, Review auf Inhalt, freundlicher Ton.", "Merge, Squash oder Rebase: im Team festlegen."],
  [S_GIT],
  [card("Pull Request", "Anfrage, Änderungen eines Branches nach Prüfung zusammenzuführen."), card("Squash", "Zusammenfassen mehrerer Commits zu einem."), card("Rebase", "Commits auf eine neue Basis setzen; ergibt eine gerade Historie.")],
  [order("Ordne den Ablauf eines Pull Requests.", ["Branch erstellen", "Committen und pushen", "Pull Request öffnen", "Prüfungen und Review", "Merge"], "Automatik und Menschen prüfen vor dem Merge."),
   mc("Warum sind kleine Pull Requests besser?", ["Schneller und gründlicher geprüft", "Sie sehen schöner aus", "Sie brauchen keine Tests", "Sie sind verpflichtend"], "Große Diffs werden oft nur überflogen."),
   mc("Was sollte ein Review nicht beschäftigen?", ["Formatierung", "Korrektheit", "Tests", "Verständlichkeit"], "Das machen Formatierer und Linter."),
   mc("Was macht Squash?", ["Fasst Commits zu einem zusammen", "Löscht den Branch", "Verschlüsselt Code", "Startet Tests"], "Ein Commit pro Änderung."),
   mc("Worauf bezieht sich gutes Feedback?", ["Auf den Code", "Auf die Person", "Auf die Kleidung", "Auf das Gehalt"], "Sachlich und konkret.")]),
 L("devops.m2.l3", "Branching-Strategien", 7, [
  "Wie lange leben Branches, und wie oft wird integriert? Davon hängt viel ab.",
  "## Git Flow",
  "Viele langlebige Branches (develop, release, hotfix, feature). Passt zu Software mit seltenen, geplanten Releases, führt aber zu großen Zusammenführungen und Konflikten.",
  "## Trunk-Based Development",
  "Alle integrieren mindestens täglich in den Hauptzweig (trunk oder main), Branches leben nur Stunden bis wenige Tage. Unfertige Funktionen werden mit Feature Flags versteckt. Die DORA-Forschung zeigt einen Zusammenhang mit hoher Lieferleistung.",
  "## Der Kern",
  "Je länger Code getrennt lebt, desto teurer wird die Integration („Merge-Hölle“). Häufige Integration hält Konflikte klein.",
  "## Releases kennzeichnen",
  "Ausgelieferte Stände werden mit Tags markiert, oft nach Semantic Versioning: MAJOR.MINOR.PATCH. MAJOR bei inkompatiblen Änderungen, MINOR bei neuen kompatiblen Funktionen, PATCH bei Fehlerbehebungen."],
  ["Git Flow: viele langlebige Branches, seltene Releases.", "Trunk-Based: täglich integrieren, kurze Branches, Feature Flags.", "Semantic Versioning: MAJOR.MINOR.PATCH."],
  [S_ACC, S_SEMVER],
  [card("Trunk-Based Development", "Alle integrieren häufig in den Hauptzweig; Branches leben kurz."), card("Feature Flag", "Schalter, mit dem Funktionen ohne neues Deployment ein- oder ausgeschaltet werden."), card("Semantic Versioning", "Versionsschema MAJOR.MINOR.PATCH nach Art der Änderung.")],
  [mc("Version 2.4.1 bekommt eine inkompatible API-Änderung. Welche Version folgt?", ["3.0.0", "2.5.0", "2.4.2", "2.4.1-neu"], "MAJOR erhöht, Rest auf 0."),
   mc("Was zeichnet Trunk-Based Development aus?", ["Tägliche Integration, kurze Branches", "Monatelange Feature-Branches", "Kein Hauptzweig", "Keine Tests"], "Konflikte bleiben klein."),
   mc("Wie versteckt man unfertige Funktionen im Hauptzweig?", ["Mit Feature Flags", "Mit Kommentaren", "Mit langen Branches", "Gar nicht"], "Code ist ausgeliefert, aber aus."),
   mc("Version 1.3.0 bekommt eine Fehlerbehebung. Welche Version folgt?", ["1.3.1", "1.4.0", "2.0.0", "1.3.0.1"], "PATCH erhöht."),
   mc("Warum wird späte Integration teuer?", ["Konflikte wachsen mit der Zeit", "Git wird langsamer", "Server kosten mehr", "Tests verschwinden"], "Die „Merge-Hölle“.")])
])

M3 = M("devops.m3", 1, "Continuous Integration", "Automatischer Build, Testpyramide, Pipelines und schnelles Feedback.", [
 L("devops.m3.l1", "Was CI bedeutet", 6, [
  "Continuous Integration (CI) heißt: Alle integrieren ihre Änderungen häufig in den Hauptzweig, und jede Integration wird automatisch gebaut und getestet.",
  "## Die Regeln",
  "Mindestens täglich integrieren. Jeder Commit löst einen automatischen Build mit Tests aus. Ein roter (fehlgeschlagener) Build wird sofort repariert, er hat Vorrang vor neuer Arbeit. Der Build ist schnell, idealerweise unter 10 Minuten.",
  "## Werkzeuge",
  "CI-Server wie Jenkins, GitLab CI, GitHub Actions oder Azure Pipelines führen Pipelines aus, die als Code im Repository beschrieben sind (etwa in YAML).",
  "## Häufiges Missverständnis",
  "Einen CI-Server zu haben ist noch keine CI. Wer wochenlang auf eigenen Branches arbeitet und nur dort Tests laufen lässt, integriert nicht kontinuierlich.",
  "Probiere unten den Pipeline-Simulator aus."],
  ["CI: häufig integrieren, jeder Commit wird gebaut und getestet.", "Roter Build hat Vorrang; Build schnell halten.", "CI-Server ≠ CI; Pipelines als Code."],
  [S_CD, S_ACC],
  [card("Continuous Integration", "Häufige Integration in den Hauptzweig mit automatischem Build und Test."), card("Roter Build", "Fehlgeschlagener Build; muss sofort repariert werden."), card("Pipeline as Code", "Beschreibung der CI/CD-Pipeline als Datei im Repository.")],
  [mc("Was hat Vorrang, wenn der Build rot ist?", ["Den Build reparieren", "Neue Features", "Feierabend", "Den Test löschen"], "Sonst bauen alle auf Fehlern auf."),
   mc("Ist ein CI-Server allein schon CI?", ["Nein, häufige Integration gehört dazu", "Ja, immer", "Nur mit Jenkins", "Nur mit YAML"], "Es geht um die Praxis."),
   mc("Wie schnell sollte ein CI-Build idealerweise sein?", ["Unter etwa 10 Minuten", "Mehrere Stunden", "Eine Woche", "Egal"], "Schnelles Feedback ist der Sinn."),
   mc("Wo wird eine moderne Pipeline beschrieben?", ["Als Code im Repository", "Auf Papier", "Nur in der Weboberfläche", "Im Kopf des Admins"], "Versioniert und prüfbar."),
   mc("Wie oft sollte man mindestens integrieren?", ["Täglich", "Monatlich", "Jährlich", "Nur beim Release"], "Kontinuierlich heißt häufig.")],
  figs=[{"after": 9, "w": "pipe", "cap": "Pipeline-Simulator: Baue einen Fehler ein und sieh, wo die Pipeline stoppt und wie schnell du es erfährst."}]),
 L("devops.m3.l2", "Die Testpyramide", 7, [
  "Automatisierte Tests sind die Sicherheitsleine für häufige Änderungen. Aber nicht alle Tests sind gleich.",
  "## Die Pyramide",
  "Unten viele Unit-Tests: Sie prüfen kleine Einheiten isoliert, laufen in Millisekunden und zeigen genau, was kaputt ist. In der Mitte Integrationstests: Sie prüfen das Zusammenspiel, etwa mit einer Datenbank. Oben wenige End-to-End-Tests: Sie prüfen das ganze System aus Nutzersicht, sind aber langsam und anfällig.",
  "## Die Eistüte",
  "Viele Teams haben es umgekehrt: kaum Unit-Tests, viele manuelle und End-to-End-Tests. Das macht Feedback langsam und Tests instabil.",
  "## Flaky Tests",
  "Tests, die mal grün, mal rot sind, ohne dass sich etwas geändert hat, zerstören Vertrauen. Sie müssen schnell repariert oder unter Quarantäne gestellt werden.",
  "## Mehr als Funktion",
  "Dazu kommen statische Analyse (Linter, Typprüfung), Sicherheitsscans und Last- oder Performancetests."],
  ["Pyramide: viele Unit-, weniger Integrations-, wenige End-to-End-Tests.", "Eistüte (umgekehrt) macht Feedback langsam.", "Flaky Tests zerstören Vertrauen: reparieren oder isolieren."],
  [S_CD],
  [card("Unit-Test", "Schneller, isolierter Test einer kleinen Code-Einheit."), card("End-to-End-Test", "Test des ganzen Systems aus Nutzersicht; langsam und aufwendig."), card("Flaky Test", "Test, der ohne Änderung mal besteht und mal fehlschlägt.")],
  [mc("Welche Tests sollte es am meisten geben?", ["Unit-Tests", "End-to-End-Tests", "Manuelle Tests", "Lasttests"], "Schnell, präzise, günstig."),
   mc("Was ist ein Flaky Test?", ["Mal grün, mal rot ohne Änderung", "Ein besonders schneller Test", "Ein Test ohne Assertions", "Ein Sicherheitstest"], "Er untergräbt Vertrauen."),
   mc("Was ist das Problem der Eistüte?", ["Langsames, instabiles Feedback", "Zu viele Unit-Tests", "Zu schnelle Builds", "Zu wenig Server"], "Viele End-to-End- und manuelle Tests."),
   order("Ordne die Testarten von schnell zu langsam.", ["Unit-Test", "Integrationstest", "End-to-End-Test"], "Je höher, desto langsamer."),
   mc("Was gehört zusätzlich in eine gute Pipeline?", ["Statische Analyse und Sicherheitsscans", "Nur manuelle Tests", "Ein Kaffeeautomat", "Nichts"], "Mehr als nur Funktionstests.")]),
 L("devops.m3.l3", "Pipelines gestalten", 6, [
  "Eine Pipeline besteht aus Stufen (Stages), die nacheinander oder parallel laufen.",
  "## Typische Stufen",
  "Checkout, Build, Unit-Tests und statische Analyse, Paketieren (Artefakt), Integrationstests, Bereitstellen in Testumgebungen, weitere Tests, Freigabe für Produktion.",
  "## Prinzipien",
  "Fail fast: Schnelle, günstige Prüfungen zuerst. Einmal bauen, überall verwenden: Dasselbe Artefakt wandert durch alle Stufen, statt pro Umgebung neu gebaut zu werden. Parallelisieren, wo möglich. Caches für Abhängigkeiten nutzen.",
  "## Artefakte und Reproduzierbarkeit",
  "Artefakte (Pakete, Container-Images, Firmware) werden versioniert in einem Repository abgelegt. Abhängigkeiten werden auf feste Versionen gepinnt, damit derselbe Commit immer dasselbe Ergebnis liefert."],
  ["Stufen: Build, Tests, Artefakt, Deploy, weitere Tests, Freigabe.", "Fail fast, einmal bauen überall verwenden, parallelisieren, cachen.", "Artefakte versioniert ablegen; Abhängigkeiten pinnen."],
  [S_CD],
  [card("Artefakt", "Ergebnis eines Builds, z. B. Paket, Container-Image oder Firmware."), card("Build once, deploy many", "Dasselbe Artefakt durchläuft alle Umgebungen."), card("Fail fast", "Schnelle Prüfungen zuerst, um früh abzubrechen.")],
  [mc("Was bedeutet „build once, deploy many“?", ["Dasselbe Artefakt für alle Umgebungen", "Für jede Umgebung neu bauen", "Nur einmal im Jahr bauen", "Nur lokal bauen"], "Sonst testet man etwas anderes als man ausliefert."),
   mc("Welche Prüfung gehört an den Anfang?", ["Schnelle Unit-Tests und Linter", "Lange Lasttests", "Manuelle Abnahme", "Produktions-Deploy"], "Fail fast."),
   mc("Warum pinnt man Abhängigkeiten?", ["Reproduzierbare Builds", "Damit sie schöner aussehen", "Weil es schneller tippt", "Damit sie verschwinden"], "Gleicher Commit, gleiches Ergebnis."),
   mc("Wo legt man Artefakte ab?", ["In einem Artefakt-Repository", "Per E-Mail", "Auf einem USB-Stick", "Im Chat"], "Versioniert und nachvollziehbar."),
   mc("Was beschleunigt Pipelines?", ["Parallelisieren und Caches", "Mehr manuelle Schritte", "Längere Tests", "Weniger Automatisierung"], "Feedback wird schneller.")])
])

M4 = M("devops.m4", 2, "Continuous Delivery und Deployment", "Auslieferungsstrategien, Feature Flags, Rollback und Release-Management.", [
 L("devops.m4.l1", "Delivery oder Deployment?", 6, [
  "Zwei Begriffe, die oft verwechselt werden.",
  "## Continuous Delivery",
  "Jede Änderung, die die Pipeline besteht, ist jederzeit auslieferbar. Ob und wann sie in Produktion geht, entscheidet ein Mensch per Knopfdruck. Der Weg dorthin ist voll automatisiert und erprobt.",
  "## Continuous Deployment",
  "Jede Änderung, die alle Prüfungen besteht, geht automatisch in Produktion, ohne manuellen Schritt. Das setzt sehr gute Tests, Überwachung und schnelle Rücknahme voraus.",
  "## Deployment ist nicht Release",
  "Deployment heißt: Code ist in Produktion installiert. Release heißt: Nutzer bekommen die Funktion. Mit Feature Flags lassen sich beide trennen. Code ist ausgerollt, aber erst später für alle eingeschaltet.",
  "## Warum es sich lohnt",
  "Kleine, häufige Auslieferungen reduzieren das Risiko pro Änderung, verkürzen die Zeit bis zum Feedback und machen Releases langweilig, und das ist gut so."],
  ["Continuous Delivery: jederzeit auslieferbar, Mensch entscheidet.", "Continuous Deployment: automatisch bis Produktion.", "Deployment ≠ Release; Feature Flags trennen beides."],
  [S_CD],
  [card("Continuous Delivery", "Jede bestandene Änderung ist jederzeit per Knopfdruck auslieferbar."), card("Continuous Deployment", "Jede bestandene Änderung geht automatisch in Produktion."), card("Release", "Freischalten einer Funktion für Nutzer, getrennt vom technischen Deployment möglich.")],
  [mc("Was unterscheidet Continuous Deployment von Delivery?", ["Kein manueller Schritt bis Produktion", "Keine Tests", "Nur nachts", "Nur für Mobile Apps"], "Delivery: Mensch drückt den Knopf."),
   mc("Was ist der Unterschied zwischen Deployment und Release?", ["Installiert vs. für Nutzer freigeschaltet", "Es gibt keinen", "Release ist technisch, Deployment fachlich", "Deployment ist nur für Hardware"], "Feature Flags trennen beides."),
   mc("Warum senken kleine Auslieferungen das Risiko?", ["Weniger Änderung pro Schritt", "Weil Server sich freuen", "Weil Tests entfallen", "Weil niemand hinschaut"], "Fehler sind leichter zu finden und zurückzunehmen."),
   mc("Was setzt Continuous Deployment voraus?", ["Sehr gute Tests und Überwachung", "Möglichst wenig Tests", "Monatliche Releases", "Manuelle Abnahme"], "Sonst gehen Fehler direkt raus."),
   mc("Was bedeutet „Releases sollen langweilig sein“?", ["Routine statt Drama", "Keine neuen Funktionen", "Lange Meetings", "Releases nur freitags"], "Häufig geübt, automatisiert, risikoarm.")]),
 L("devops.m4.l2", "Auslieferungsstrategien", 7, [
  "Wie bringt man eine neue Version in Produktion, ohne alle Nutzer zu gefährden?",
  "## Rolling Update",
  "Instanzen werden nach und nach ersetzt. Einfach und ohne doppelte Ressourcen, aber eine Zeit lang laufen alte und neue Version gemischt.",
  "## Blue/Green",
  "Zwei vollständige Umgebungen. Die neue Version (Green) wird neben der laufenden (Blue) aufgebaut und getestet, dann wird der Verkehr umgeschaltet. Rücknahme heißt: zurückschalten. Nachteil: doppelte Ressourcen.",
  "## Canary",
  "Die neue Version bekommt zuerst einen kleinen Teil des Verkehrs, etwa 1 bis 5 %. Kennzahlen wie Fehlerrate und Latenz werden verglichen. Ist alles gut, wird schrittweise erhöht, sonst zurückgerollt. Name nach den Kanarienvögeln, die Bergleute vor Gas warnten.",
  "## Datenbanken",
  "Schwierig sind Schemaänderungen. Bewährt ist das Expand-Contract-Muster: erst erweitern (neue Spalte, alter und neuer Code funktionieren), dann umstellen, zuletzt Altes entfernen."],
  ["Rolling: schrittweise ersetzen.", "Blue/Green: umschalten, schnelles Zurück, doppelte Ressourcen.", "Canary: kleiner Anteil zuerst, nach Kennzahlen erhöhen; Expand-Contract für Datenbanken."],
  [S_CD, S_SRE],
  [card("Blue/Green Deployment", "Zwei Umgebungen; Verkehr wird auf die neue umgeschaltet."), card("Canary Release", "Neue Version erst für einen kleinen Anteil, dann schrittweise mehr."), card("Expand-Contract", "Schemaänderung in Schritten: erweitern, umstellen, Altes entfernen.")],
  [mc("Was ist ein Nachteil von Blue/Green?", ["Doppelte Ressourcen", "Kein Rollback möglich", "Nur für Datenbanken", "Sehr langsames Umschalten"], "Zwei vollständige Umgebungen."),
   mc("Wie viel Verkehr bekommt ein Canary anfangs typischerweise?", ["1 bis 5 %", "100 %", "50 %", "0 %"], "Klein starten, dann erhöhen."),
   mc("Was vergleicht man beim Canary?", ["Fehlerrate und Latenz", "Farben der Oberfläche", "Anzahl der Entwickler", "Lizenzkosten"], "Gegen die alte Version."),
   order("Ordne das Expand-Contract-Muster.", ["Schema erweitern", "Code umstellen", "Altes entfernen"], "Immer kompatibel bleiben."),
   mc("Was passiert beim Rolling Update?", ["Instanzen werden nach und nach ersetzt", "Alles wird gleichzeitig ersetzt", "Nichts", "Nur Datenbanken werden ersetzt"], "Zeitweise laufen beide Versionen.")]),
 L("devops.m4.l3", "Feature Flags und Rollback", 6, [
  "Zwei Werkzeuge machen Auslieferung sicher: Schalter und Rückwege.",
  "## Feature Flags",
  "Ein Flag schaltet eine Funktion zur Laufzeit ein oder aus, für alle, für bestimmte Gruppen oder für einen Prozentsatz. So lassen sich Funktionen testen, schrittweise freigeben oder bei Problemen sofort abschalten (Kill Switch).",
  "## Flag-Schulden",
  "Jedes Flag verdoppelt mögliche Pfade im Code. Alte Flags müssen entfernt werden, sonst wird der Code unübersichtlich und riskant.",
  "## Rollback oder Roll Forward",
  "Rollback heißt: auf die vorige Version zurück. Roll Forward heißt: schnell eine korrigierte Version ausliefern. Beides muss geübt sein. Rollback wird schwierig, wenn Datenformate schon geändert wurden; deshalb Expand-Contract.",
  "## Automatische Rücknahme",
  "Fortgeschrittene Pipelines überwachen nach dem Deployment Kennzahlen und nehmen bei Verschlechterung automatisch zurück."],
  ["Feature Flags: Laufzeitschalter, schrittweise Freigabe, Kill Switch.", "Alte Flags entfernen, sonst Flag-Schulden.", "Rollback oder Roll Forward; automatische Rücknahme nach Kennzahlen."],
  [S_CD],
  [card("Kill Switch", "Flag, mit dem eine fehlerhafte Funktion sofort abgeschaltet wird."), card("Roll Forward", "Fehlerbehebung durch schnelle Auslieferung einer korrigierten Version."), card("Flag-Schulden", "Unübersichtlichkeit durch alte, nicht entfernte Feature Flags.")],
  [mc("Was ist ein Kill Switch?", ["Flag zum sofortigen Abschalten", "Ein Not-Aus am Server", "Ein Löschbefehl für Git", "Ein Virenscanner"], "Ohne neues Deployment."),
   mc("Warum müssen alte Flags entfernt werden?", ["Sie vervielfachen Codepfade", "Sie kosten Lizenzgebühren", "Sie verlangsamen Git", "Gar nicht nötig"], "Flag-Schulden."),
   mc("Was ist Roll Forward?", ["Korrigierte Version schnell ausliefern", "Alte Version wiederherstellen", "Server neu starten", "Alles löschen"], "Statt zurück nach vorn."),
   mc("Wann wird ein Rollback schwierig?", ["Wenn Datenformate schon geändert sind", "Wenn der Build grün ist", "Wenn es regnet", "Wenn Tests existieren"], "Deshalb Expand-Contract."),
   mc("Was können Feature Flags zusätzlich?", ["Prozentuale Freigabe", "Code kompilieren", "Server kühlen", "Passwörter speichern"], "Etwa 10 % der Nutzer.")])
])

M5 = M("devops.m5", 2, "Container und Kubernetes", "Images, Container, Orchestrierung, Deployments, Services und Probes.", [
 L("devops.m5.l1", "Container verstehen", 7, [
  "„Bei mir läuft es“ war jahrzehntelang ein Problem: Software verhielt sich je nach Rechner anders. Container lösen das, indem sie Anwendung und Abhängigkeiten zusammen verpacken.",
  "## Container vs. virtuelle Maschine",
  "Eine virtuelle Maschine emuliert einen ganzen Rechner mit eigenem Betriebssystem. Ein Container teilt sich den Kernel des Hosts und isoliert nur Prozesse, Dateisystem und Netzwerk (unter Linux über Namespaces und cgroups). Container starten daher in Sekunden und brauchen wenig Ressourcen, isolieren aber schwächer.",
  "## Images und Schichten",
  "Ein Image ist eine unveränderliche Vorlage, beschrieben in einem Dockerfile. Jede Anweisung erzeugt eine Schicht (Layer); unveränderte Schichten werden zwischengespeichert. Multi-Stage-Builds trennen Bau- und Laufzeitumgebung und machen Images klein.",
  "## Gute Praxis",
  "Kleine Basis-Images, keine Geheimnisse im Image, nicht als root laufen, ein Prozess pro Container, Konfiguration über Umgebungsvariablen. Images werden in einer Registry gespeichert und mit Tags oder besser einem Digest eindeutig referenziert."],
  ["Container teilen den Kernel; VM emuliert ganzen Rechner.", "Image = unveränderliche Vorlage mit Schichten (Dockerfile).", "Kleine Images, keine Geheimnisse, nicht root, Digest statt nur Tag."],
  [S_DOCKER, S_12F],
  [card("Container", "Isolierter Prozess mit eigener Sicht auf Dateisystem und Netzwerk, teilt den Host-Kernel."), card("Image", "Unveränderliche Vorlage für Container, aus Schichten aufgebaut."), card("Multi-Stage-Build", "Dockerfile mit getrennten Bau- und Laufzeitstufen für kleine Images."), card("Digest", "Hash eines Images; eindeutige, unveränderliche Referenz.")],
  [mc("Was teilen sich Container mit dem Host?", ["Den Kernel", "Nichts", "Die Festplatte komplett", "Den Bildschirm"], "Deshalb starten sie so schnell."),
   mc("Was erzeugt jede Anweisung im Dockerfile?", ["Eine Schicht", "Einen Container", "Einen Server", "Einen Branch"], "Schichten werden gecacht."),
   mc("Wozu dienen Multi-Stage-Builds?", ["Kleine Laufzeit-Images", "Mehr Sicherheitslücken", "Längere Builds", "Mehr Tags"], "Compiler bleiben draußen."),
   mc("Warum referenziert man Images besser per Digest?", ["Eindeutig und unveränderlich", "Kürzer zu tippen", "Schöner", "Weil Tags verboten sind"], "Ein Tag wie „latest“ kann sich ändern."),
   mc("Was gehört nicht in ein Image?", ["Passwörter und Schlüssel", "Die Anwendung", "Ihre Abhängigkeiten", "Ein Startbefehl"], "Geheimnisse kommen zur Laufzeit.")]),
 L("devops.m5.l2", "Kubernetes-Grundlagen", 7, [
  "Viele Container auf vielen Servern zu betreiben, braucht einen Orchestrator. Der Standard ist Kubernetes (K8s), 2014 von Google als Open Source veröffentlicht und heute von der CNCF betreut.",
  "## Deklarativ",
  "Man beschreibt den gewünschten Zustand in YAML, etwa „drei Instanzen dieses Images“. Kubernetes vergleicht ständig Soll und Ist und gleicht ab (Reconciliation). Stirbt ein Container, startet es einen neuen.",
  "## Wichtige Objekte",
  "Pod: kleinste Einheit, ein oder wenige Container mit gemeinsamer Netzwerkadresse. Deployment: verwaltet Pods einer Anwendung inklusive Rolling Updates. Service: stabile Adresse und Lastverteilung für wechselnde Pods. Ingress: Zugang von außen per HTTP. ConfigMap und Secret: Konfiguration und Geheimnisse. Namespace: logische Trennung.",
  "## Architektur",
  "Die Control Plane (API-Server, Scheduler, Controller, etcd als Datenspeicher) trifft Entscheidungen. Auf den Worker-Knoten startet der kubelet die Container."],
  ["Kubernetes: Orchestrator, seit 2014, CNCF.", "Deklarativ: Soll beschreiben, Kubernetes gleicht ab.", "Pod, Deployment, Service, Ingress, ConfigMap, Secret, Namespace."],
  [S_K8S],
  [card("Pod", "Kleinste Kubernetes-Einheit aus einem oder wenigen Containern."), card("Deployment (K8s)", "Verwaltet die Pods einer Anwendung, inklusive Updates und Skalierung."), card("Service (K8s)", "Stabile Adresse und Lastverteilung für wechselnde Pods."), card("Reconciliation", "Ständiger Abgleich von Soll- und Ist-Zustand.")],
  [mc("Was ist die kleinste Einheit in Kubernetes?", ["Pod", "Node", "Cluster", "Image"], "Ein oder wenige Container."),
   mc("Was bietet ein Service?", ["Stabile Adresse für wechselnde Pods", "Speicherplatz", "Ein Image", "Ein Git-Repository"], "Pods kommen und gehen."),
   mc("Was bedeutet deklarativ?", ["Soll beschreiben, System gleicht ab", "Jeden Schritt einzeln befehlen", "Nur Dokumentation", "Code ohne Tests"], "Reconciliation."),
   mc("Wo speichert Kubernetes seinen Zustand?", ["In etcd", "In Git", "In Excel", "Im Browser"], "Ein verteilter Schlüssel-Wert-Speicher."),
   mc("Was startet auf den Worker-Knoten die Container?", ["Der kubelet", "Der Scheduler", "Ingress", "etcd"], "Der Scheduler entscheidet nur wo.")]),
 L("devops.m5.l3", "Betrieb in Kubernetes", 7, [
  "Damit Anwendungen in Kubernetes stabil laufen, braucht es ein paar Bausteine.",
  "## Probes",
  "Die Liveness-Probe prüft, ob ein Container noch lebt; schlägt sie fehl, wird er neu gestartet. Die Readiness-Probe prüft, ob er Anfragen annehmen kann; bis dahin bekommt er keinen Verkehr. Die Startup-Probe schützt langsam startende Anwendungen.",
  "## Ressourcen",
  "Requests reservieren CPU und Speicher für die Planung, Limits begrenzen den Verbrauch. Überschreitet ein Container sein Speicherlimit, wird er beendet (OOMKilled).",
  "## Skalierung",
  "Der Horizontal Pod Autoscaler erhöht oder senkt die Zahl der Pods anhand von Kennzahlen wie CPU-Last. Cluster-Autoscaler fügen Knoten hinzu.",
  "## Typische Fehler",
  "CrashLoopBackOff (Container stürzt immer wieder ab), ImagePullBackOff (Image nicht ladbar), Pending (keine passende Ressource frei). Erste Schritte: kubectl describe und kubectl logs.",
  "## Ehrlicher Hinweis",
  "Kubernetes ist mächtig, aber komplex. Für kleine Anwendungen sind einfachere Plattformen oft die bessere Wahl."],
  ["Liveness (neu starten), Readiness (Verkehr), Startup (langsamer Start).", "Requests und Limits; Speicherlimit überschritten → OOMKilled.", "HPA skaliert; Fehler: CrashLoopBackOff, ImagePullBackOff, Pending."],
  [S_K8S],
  [card("Liveness-Probe", "Prüft, ob ein Container lebt; bei Fehlschlag Neustart."), card("Readiness-Probe", "Prüft, ob ein Container Anfragen annehmen kann."), card("OOMKilled", "Container wurde wegen Überschreitung des Speicherlimits beendet."), card("CrashLoopBackOff", "Container stürzt wiederholt ab; Kubernetes wartet zunehmend länger.")],
  [mc("Was passiert, wenn die Readiness-Probe fehlschlägt?", ["Der Pod bekommt keinen Verkehr", "Der Pod wird gelöscht", "Der Cluster startet neu", "Nichts"], "Neustart wäre Liveness."),
   mc("Was bedeutet OOMKilled?", ["Speicherlimit überschritten", "Image nicht gefunden", "Netzwerk getrennt", "Probe zu langsam"], "Out of Memory."),
   mc("Was zeigt ImagePullBackOff?", ["Image kann nicht geladen werden", "Speicher voll", "Zu viel Verkehr", "Pod ist fertig"], "Falscher Name, Tag oder fehlende Rechte."),
   mc("Was skaliert der Horizontal Pod Autoscaler?", ["Die Anzahl der Pods", "Die Größe der Images", "Die Zahl der Entwickler", "Die Bandbreite"], "Anhand von Kennzahlen wie CPU."),
   mc("Womit beginnt man die Fehlersuche bei einem Pod?", ["kubectl describe und logs", "Server ausschalten", "Image löschen", "Neuen Cluster bauen"], "Ereignisse und Ausgaben lesen.")])
])

M6 = M("devops.m6", 2, "Infrastructure as Code und GitOps", "Infrastruktur als Code, Zustandsverwaltung, Konfigurationsmanagement und GitOps.", [
 L("devops.m6.l1", "Infrastructure as Code", 7, [
  "Server, Netzwerke und Datenbanken per Hand einzurichten ist langsam, fehleranfällig und nicht nachvollziehbar. Infrastructure as Code (IaC) beschreibt Infrastruktur in versionierten Dateien.",
  "## Deklarativ mit Terraform",
  "Terraform (und der offene Fork OpenTofu, entstanden 2023 nach einer Lizenzänderung) beschreibt Ressourcen in HCL. terraform plan zeigt, was sich ändern würde, terraform apply setzt es um. Eine Zustandsdatei (State) merkt sich, welche realen Ressourcen zu welcher Beschreibung gehören; sie muss geschützt und gemeinsam genutzt werden (Remote State mit Sperre).",
  "## Weitere Werkzeuge",
  "Cloud-eigene Werkzeuge (z. B. CloudFormation), Pulumi mit gängigen Programmiersprachen, Crossplane in Kubernetes.",
  "## Drift",
  "Ändert jemand die Infrastruktur per Hand, weicht die Realität vom Code ab (Drift). Regelmäßige Plans zeigen Drift; die Regel lautet: Änderungen nur über Code."],
  ["IaC: Infrastruktur versioniert in Dateien.", "Terraform/OpenTofu: plan zeigt, apply setzt um; State schützen.", "Drift vermeiden: Änderungen nur über Code."],
  [S_TF],
  [card("Infrastructure as Code", "Beschreibung von Infrastruktur in versionierten Dateien."), card("Terraform State", "Datei, die Beschreibung und reale Ressourcen verknüpft."), card("Drift", "Abweichung der realen Infrastruktur vom Code."), card("terraform plan", "Zeigt geplante Änderungen, ohne sie umzusetzen.")],
  [mc("Was zeigt terraform plan?", ["Geplante Änderungen ohne Umsetzung", "Die Kosten der Firma", "Den Git-Verlauf", "Die Logs"], "Apply setzt sie dann um."),
   mc("Was ist Drift?", ["Realität weicht vom Code ab", "Ein Autorennen", "Ein Git-Befehl", "Ein Container-Fehler"], "Meist durch Handänderungen."),
   mc("Warum muss der State geschützt werden?", ["Er verknüpft Code und reale Ressourcen", "Er enthält Musik", "Er ist leer", "Er ist unwichtig"], "Enthält oft auch sensible Werte."),
   mc("Was ist OpenTofu?", ["Offener Fork von Terraform", "Eine Datenbank", "Ein Container", "Eine CI-Plattform"], "Entstanden 2023 nach Lizenzänderung."),
   mc("Was ist die Regel gegen Drift?", ["Änderungen nur über Code", "Häufiger per Hand ändern", "State löschen", "Plans vermeiden"], "Und Drift regelmäßig prüfen.")]),
 L("devops.m6.l2", "Unveränderliche Infrastruktur", 6, [
  "Früher wurden Server über Jahre gepflegt und gepatcht. Jeder war ein wenig anders (Schneeflocke).",
  "## Pets vs. Cattle",
  "Haustiere (Pets) haben Namen und werden gepflegt. Nutztiere (Cattle) sind gleichartig und werden ersetzt, wenn sie krank sind. Moderne Infrastruktur behandelt Server wie Cattle.",
  "## Immutable Infrastructure",
  "Statt einen laufenden Server zu ändern, baut man ein neues Image mit der Änderung und ersetzt die alten Instanzen. Konfiguration ist damit reproduzierbar, und Rücknahme heißt: altes Image wieder verwenden.",
  "## Konfigurationsmanagement",
  "Werkzeuge wie Ansible (agentenlos über SSH), Puppet oder Chef bringen Systeme in einen beschriebenen Zustand. Sie sind idempotent: mehrfaches Ausführen ergibt dasselbe Ergebnis. Sie werden heute oft zum Bauen von Images statt zum Ändern laufender Server genutzt."],
  ["Pets (gepflegt) vs. Cattle (ersetzt).", "Immutable: neues Image bauen statt Server ändern.", "Konfigurationsmanagement idempotent, z. B. Ansible über SSH."],
  [S_DOH, S_12F],
  [card("Immutable Infrastructure", "Server werden nicht geändert, sondern durch neu gebaute ersetzt."), card("Idempotent", "Mehrfache Ausführung ergibt dasselbe Ergebnis."), card("Pets vs. Cattle", "Bild für individuell gepflegte vs. austauschbare Server.")],
  [mc("Was bedeutet idempotent?", ["Mehrfach ausführen, gleiches Ergebnis", "Nur einmal ausführbar", "Zufälliges Ergebnis", "Nie ausführbar"], "Wichtig für Automatisierung."),
   mc("Wie ändert man immutable Infrastruktur?", ["Neues Image bauen und ersetzen", "Per SSH patchen", "Gar nicht", "Per Telefon"], "Rücknahme: altes Image."),
   mc("Wie arbeitet Ansible?", ["Agentenlos über SSH", "Nur mit Agenten", "Über FTP", "Per E-Mail"], "Keine Software auf dem Zielsystem nötig."),
   mc("Was ist ein Schneeflocken-Server?", ["Einzigartig gewachsen, schwer reproduzierbar", "Ein gekühlter Server", "Ein neuer Server", "Ein Cloud-Dienst"], "Genau das will man vermeiden."),
   mc("Wie behandelt man Server als Cattle?", ["Gleichartig und austauschbar", "Mit Namen und Pflege", "Nie neu starten", "Nur manuell"], "Krank → ersetzen.")]),
 L("devops.m6.l3", "GitOps", 6, [
  "GitOps überträgt das Prinzip von Pull Requests auf den Betrieb.",
  "## Die Prinzipien (OpenGitOps)",
  "Der gewünschte Zustand ist deklarativ beschrieben, versioniert und unveränderlich gespeichert (meist in Git), wird automatisch gezogen (pull) und kontinuierlich abgeglichen.",
  "## So funktioniert es",
  "Ein Agent im Cluster, etwa Argo CD oder Flux, beobachtet ein Git-Repository und gleicht den Cluster ständig damit ab. Wer etwas ändern will, öffnet einen Pull Request. Nach dem Merge zieht der Agent die Änderung.",
  "## Vorteile",
  "Volle Nachvollziehbarkeit (Git-Historie als Änderungsprotokoll), einfaches Zurücknehmen (git revert), weniger Zugriffsrechte nötig (die CI muss nicht in den Cluster schreiben), Drift wird automatisch korrigiert.",
  "## Push vs. Pull",
  "Klassische Pipelines pushen Änderungen in die Umgebung. GitOps zieht sie aus Git. Das verringert die Angriffsfläche, weil keine Pipeline dauerhaft Schreibrechte auf Produktion braucht."],
  ["GitOps: deklarativ, versioniert, gezogen, kontinuierlich abgeglichen.", "Agent (Argo CD, Flux) gleicht Cluster mit Git ab.", "Nachvollziehbar, einfach zurückzunehmen, weniger Rechte (Pull statt Push)."],
  [S_GITOPS],
  [card("GitOps", "Betrieb über deklarativen, in Git versionierten Zustand, den ein Agent automatisch abgleicht."), card("Argo CD / Flux", "Verbreitete GitOps-Agenten für Kubernetes."), card("Pull-basiertes Deployment", "Die Umgebung zieht Änderungen selbst, statt sie von außen zu bekommen.")],
  [mc("Wer gleicht bei GitOps den Cluster ab?", ["Ein Agent im Cluster", "Ein Mensch per Hand", "Die CI per Push", "Niemand"], "Etwa Argo CD oder Flux."),
   mc("Wie nimmt man bei GitOps eine Änderung zurück?", ["git revert", "Server neu installieren", "Cluster löschen", "Per E-Mail"], "Der Agent zieht den alten Stand."),
   mc("Warum ist Pull sicherer als Push?", ["Keine Pipeline braucht Schreibrechte auf Produktion", "Pull ist schneller", "Push ist verboten", "Pull braucht kein Netzwerk"], "Kleinere Angriffsfläche."),
   mc("Was passiert bei Drift unter GitOps?", ["Sie wird automatisch korrigiert", "Sie bleibt", "Der Cluster stürzt ab", "Git wird gelöscht"], "Kontinuierlicher Abgleich."),
   mc("Was dient bei GitOps als Änderungsprotokoll?", ["Die Git-Historie", "Ein Excel-Blatt", "Das Gedächtnis", "Der Chat"], "Wer, was, wann, warum.")])
])

M7 = M("devops.m7", 3, "Observability und SRE", "Metriken, Logs, Traces, SLOs, Fehlerbudgets und Umgang mit Störungen.", [
 L("devops.m7.l1", "Beobachtbarkeit", 7, [
  "Monitoring sagt, ob etwas kaputt ist. Observability hilft zu verstehen, warum, auch bei Fehlern, die niemand vorhergesehen hat.",
  "## Drei Signale",
  "Metriken: Zahlen über Zeit, etwa Anfragen pro Sekunde oder Fehlerrate; günstig und gut für Alarme. Logs: einzelne Ereignisse mit Details; am besten strukturiert (etwa JSON). Traces: der Weg einer Anfrage durch viele Dienste, mit Zeit pro Schritt.",
  "## Standards",
  "OpenTelemetry ist ein offener Standard zum Erfassen von Metriken, Logs und Traces, unabhängig vom Anbieter. Verbreitet sind Prometheus für Metriken und Grafana für Dashboards.",
  "## Was messen?",
  "Die vier goldenen Signale aus dem Google-SRE-Buch: Latenz, Verkehr, Fehler und Sättigung. Für Dienste die RED-Methode (Rate, Errors, Duration), für Ressourcen die USE-Methode (Utilization, Saturation, Errors).",
  "## Gute Alarme",
  "Alarmieren auf Symptome, die Nutzer spüren, nicht auf jede Ursache. Jeder Alarm braucht eine klare Handlung, sonst entsteht Alarmmüdigkeit."],
  ["Metriken, Logs, Traces; OpenTelemetry als Standard.", "Goldene Signale: Latenz, Verkehr, Fehler, Sättigung; RED und USE.", "Auf Nutzersymptome alarmieren, jeder Alarm mit Handlung."],
  [S_SRE, S_OTEL],
  [card("Trace", "Aufzeichnung des Wegs einer Anfrage durch mehrere Dienste."), card("Vier goldene Signale", "Latenz, Verkehr, Fehler, Sättigung."), card("OpenTelemetry", "Offener Standard zur Erfassung von Metriken, Logs und Traces."), card("Alarmmüdigkeit", "Abstumpfung durch zu viele, oft unnötige Alarme.")],
  [mc("Was zeigt ein Trace?", ["Weg einer Anfrage durch Dienste", "Die CPU-Temperatur", "Den Git-Verlauf", "Die Kosten"], "Mit Zeit pro Schritt."),
   multi("Welche gehören zu den vier goldenen Signalen?", ["Latenz", "Fehler", "Sättigung", "Codezeilen"], [0, 1, 2], "Das vierte ist Verkehr."),
   mc("Worauf sollte man vorrangig alarmieren?", ["Auf Symptome, die Nutzer spüren", "Auf jede kleine Ursache", "Auf nichts", "Auf Commits"], "Sonst Alarmmüdigkeit."),
   mc("Wofür steht RED?", ["Rate, Errors, Duration", "Red, Error, Danger", "Run, Execute, Deploy", "Read, Edit, Delete"], "Für Dienste."),
   mc("Was ist OpenTelemetry?", ["Offener Standard für Telemetrie", "Ein Cloud-Anbieter", "Eine Datenbank", "Ein Git-Server"], "Anbieterunabhängig.")]),
 L("devops.m7.l2", "SLI, SLO und Fehlerbudget", 7, [
  "Site Reliability Engineering (SRE) wurde bei Google entwickelt: Betrieb als Ingenieursdisziplin. Zentrales Werkzeug sind Zuverlässigkeitsziele.",
  "## Begriffe",
  "Ein SLI (Service Level Indicator) misst etwas, das Nutzern wichtig ist, etwa den Anteil erfolgreicher Anfragen unter 300 ms. Ein SLO (Objective) ist das Ziel dafür, etwa 99,9 % über 30 Tage. Ein SLA (Agreement) ist ein Vertrag mit Konsequenzen, meist lockerer als das SLO.",
  "## Fehlerbudget",
  "100 % ist unrealistisch und unnötig teuer. Die Differenz zum SLO ist das Fehlerbudget: Bei 99,9 % über 30 Tage sind das etwa 43 Minuten Ausfall. Solange Budget übrig ist, darf das Team riskantere Änderungen ausliefern. Ist es aufgebraucht, hat Stabilität Vorrang.",
  "## Warum das wirkt",
  "Das Fehlerbudget löst den alten Streit zwischen Tempo und Stabilität mit einer gemeinsamen, messbaren Regel.",
  "Rechne unten mit dem SLO-Rechner."],
  ["SLI misst, SLO ist das Ziel, SLA ist der Vertrag.", "Fehlerbudget = 100 % − SLO; 99,9 % / 30 Tage ≈ 43 min.", "Budget übrig: Tempo; Budget weg: Stabilität."],
  [S_SRE],
  [card("SLI", "Service Level Indicator: Messgröße für Zuverlässigkeit aus Nutzersicht."), card("SLO", "Service Level Objective: Zielwert für einen SLI."), card("SLA", "Service Level Agreement: Vertrag mit Konsequenzen bei Verfehlung."), card("Fehlerbudget", "Erlaubte Unzuverlässigkeit: 100 % minus SLO.")],
  [num("Wie viele Minuten Ausfall erlaubt ein SLO von 99,9 % über 30 Tage?", 43.2, "min", 0.5, "30 × 24 × 60 = 43.200 min, davon 0,1 % = 43,2 min."),
   num("Wie viele Minuten erlaubt 99,99 % über 30 Tage?", 4.32, "min", 0.1, "0,01 % von 43.200 min."),
   mc("Was passiert, wenn das Fehlerbudget aufgebraucht ist?", ["Stabilität hat Vorrang", "Mehr riskante Releases", "SLO wird gelöscht", "Nichts"], "Gemeinsame Regel statt Streit."),
   mc("Was ist meist lockerer: SLO oder SLA?", ["Das SLA", "Das SLO", "Beide gleich", "Keins"], "Puffer zwischen Ziel und Vertrag."),
   mc("Warum ist 100 % kein gutes Ziel?", ["Unrealistisch und sehr teuer", "Zu einfach", "Verboten", "Nicht messbar"], "Nutzer merken den Unterschied oft nicht.")],
  figs=[{"after": 9, "w": "slo", "cap": "SLO-Rechner: Wähle ein Ziel und sieh, wie Störungen das Fehlerbudget aufbrauchen."}]),
 L("devops.m7.l3", "Störungen und Postmortems", 6, [
  "Störungen passieren. Entscheidend ist, wie ein Team reagiert und lernt.",
  "## Incident Management",
  "Klare Rollen helfen: Incident Commander koordiniert, andere untersuchen und beheben, eine Person kommuniziert nach außen. Ziel ist zuerst die Wiederherstellung (Mitigation), die Ursachenanalyse kommt danach.",
  "## Rufbereitschaft",
  "Wer betreibt, ist auch erreichbar (On-Call). Gute Rufbereitschaft ist fair verteilt, hat Runbooks für bekannte Probleme und wenige, sinnvolle Alarme.",
  "## Blameless Postmortem",
  "Nach einer Störung schreibt das Team einen Bericht: Ablauf, Auswirkung, Ursachen, was gut lief, was nicht, konkrete Maßnahmen. Ohne Schuldzuweisung: Menschen handeln mit dem Wissen, das sie hatten; die Frage ist, wie das System Fehler zuließ. Nur so sprechen Menschen offen über Fehler.",
  "## Lernen",
  "Maßnahmen werden verfolgt und umgesetzt. Manche Teams üben Ausfälle gezielt (Chaos Engineering, Game Days), um Schwächen zu finden, bevor sie Kunden treffen."],
  ["Rollen: Incident Commander, Untersuchung, Kommunikation; erst wiederherstellen.", "On-Call fair, mit Runbooks und sinnvollen Alarmen.", "Blameless Postmortem; Chaos Engineering zum Üben."],
  [S_SRE],
  [card("Incident Commander", "Koordiniert die Reaktion auf eine Störung."), card("Runbook", "Anleitung für den Umgang mit bekannten Problemen."), card("Blameless Postmortem", "Störungsbericht ohne Schuldzuweisung mit Fokus auf Systemverbesserung."), card("Chaos Engineering", "Gezieltes Einbringen von Fehlern, um Schwächen zu finden.")],
  [mc("Was hat bei einer Störung zuerst Vorrang?", ["Wiederherstellung", "Schuldige finden", "Ursachenanalyse in Ruhe", "Dokumentation"], "Erst den Schaden begrenzen."),
   mc("Warum sind Postmortems „blameless“?", ["Damit offen über Fehler gesprochen wird", "Weil niemand Fehler macht", "Weil es Zeit spart", "Weil Chefs es nicht lesen"], "Systeme verbessern statt Menschen bestrafen."),
   mc("Was ist ein Runbook?", ["Anleitung für bekannte Probleme", "Ein Laufband", "Ein Git-Branch", "Ein Container"], "Hilft auch nachts um drei."),
   mc("Was ist Chaos Engineering?", ["Fehler gezielt einbringen und lernen", "Unordnung im Code", "Zufällige Releases", "Server ohne Plan"], "Etwa an Game Days."),
   mc("Was koordiniert der Incident Commander?", ["Die Reaktion auf die Störung", "Die Urlaubsplanung", "Das Budget", "Das Marketing"], "Er muss nicht selbst reparieren.")])
])

M8 = M("devops.m8", 3, "DevSecOps und DevOps im Fahrzeug", "Sicherheit in der Pipeline, Lieferkette und DevOps für eingebettete Software.", [
 L("devops.m8.l1", "Sicherheit in der Pipeline", 7, [
  "DevSecOps bedeutet: Sicherheit ist von Anfang an Teil des Ablaufs, nicht eine Prüfung kurz vor dem Release (Shift Left).",
  "## Automatisierte Prüfungen",
  "SAST (statische Analyse des Quellcodes auf Schwachstellen), SCA (Prüfung der Abhängigkeiten auf bekannte Lücken), DAST (Tests gegen die laufende Anwendung), Container- und IaC-Scans sowie Secret-Scanning (versehentlich eingecheckte Passwörter und Schlüssel).",
  "## Geheimnisse",
  "Passwörter und Schlüssel gehören nie ins Repository. Sie liegen in einem Secret-Manager (etwa Vault oder dem Dienst der Cloud) und werden zur Laufzeit bereitgestellt. Wurde ein Geheimnis eingecheckt, reicht Löschen nicht; es muss ausgetauscht werden, weil es in der Historie bleibt.",
  "## Minimale Rechte",
  "Pipelines und Dienste bekommen nur die Rechte, die sie wirklich brauchen. Kurzlebige Zugangsdaten (etwa über OIDC) sind besser als langlebige Token."],
  ["Shift Left: Sicherheit früh und automatisch.", "SAST, SCA, DAST, Container-/IaC-Scans, Secret-Scanning.", "Geheimnisse im Secret-Manager; geleakte austauschen; minimale Rechte."],
  [S_OWASP],
  [card("SAST", "Statische Sicherheitsanalyse des Quellcodes."), card("SCA", "Software Composition Analysis: Prüfung von Abhängigkeiten auf bekannte Schwachstellen."), card("DAST", "Dynamische Sicherheitstests gegen die laufende Anwendung."), card("Shift Left", "Prüfungen möglichst früh im Ablauf durchführen.")],
  [mc("Was prüft SCA?", ["Abhängigkeiten auf bekannte Lücken", "Den eigenen Code statisch", "Die laufende Anwendung", "Die Hardware"], "Software Composition Analysis."),
   mc("Ein Passwort wurde versehentlich gepusht. Was ist zu tun?", ["Passwort austauschen", "Nur die Datei löschen", "Nichts", "Den Commit umbenennen"], "Es bleibt in der Historie."),
   mc("Was bedeutet Shift Left?", ["Sicherheit früh im Ablauf", "Code nach links einrücken", "Später testen", "Server umziehen"], "Früh ist billiger."),
   mc("Was ist besser als langlebige Token?", ["Kurzlebige Zugangsdaten", "Passwörter im Code", "Geteilte Admin-Konten", "Keine Anmeldung"], "Etwa über OIDC."),
   mc("Was testet DAST?", ["Die laufende Anwendung", "Nur Quellcode", "Nur Abhängigkeiten", "Nur Dokumentation"], "Dynamisch, von außen.")]),
 L("devops.m8.l2", "Die Software-Lieferkette", 7, [
  "Moderne Software besteht großteils aus fremden Bausteinen. Angriffe auf diese Lieferkette treffen viele auf einmal.",
  "## Warnende Beispiele",
  "Ende 2021 betraf die Lücke Log4Shell in der weit verbreiteten Java-Bibliothek Log4j unzählige Systeme. Andere Angriffe manipulierten Build-Systeme oder Pakete in öffentlichen Registries, etwa durch täuschend ähnliche Paketnamen.",
  "## Gegenmaßnahmen",
  "SBOM (Software Bill of Materials, etwa in den Formaten SPDX oder CycloneDX) listet alle Bestandteile; bei einer neuen Lücke weiß man sofort, wer betroffen ist. Signierte Artefakte (etwa mit Sigstore/cosign) beweisen Herkunft und Unverändertheit. Provenienz-Nachweise beschreiben, wie ein Artefakt gebaut wurde.",
  "## SLSA",
  "Das Rahmenwerk SLSA beschreibt Stufen für eine vertrauenswürdige Lieferkette: von dokumentiertem Build bis zu gehärteten, isolierten Build-Systemen mit fälschungssicherer Provenienz.",
  "## Regulierung",
  "Regeln wie der EU Cyber Resilience Act oder im Fahrzeug UN R155 machen Lieferkettensicherheit zunehmend zur Pflicht."],
  ["Lieferkettenangriffe treffen viele (z. B. Log4Shell 2021).", "SBOM (SPDX, CycloneDX), signierte Artefakte, Provenienz.", "SLSA-Stufen; Regulierung macht es zur Pflicht."],
  [S_SLSA, S_OWASP],
  [card("SBOM", "Liste aller Softwarebestandteile, z. B. im Format SPDX oder CycloneDX."), card("Provenienz", "Nachweis, wie und woraus ein Artefakt gebaut wurde."), card("SLSA", "Rahmenwerk mit Stufen für Lieferkettensicherheit."), card("Log4Shell", "Schwere Lücke in Log4j (2021), Beispiel für Lieferkettenrisiken.")],
  [mc("Wozu dient eine SBOM?", ["Betroffene Software schnell finden", "Server kühlen", "Code formatieren", "Kosten senken"], "Liste aller Bestandteile."),
   mc("Was beweist eine Signatur am Artefakt?", ["Herkunft und Unverändertheit", "Dass es fehlerfrei ist", "Dass es schnell ist", "Dass es billig ist"], "Nicht die Qualität."),
   mc("Was war Log4Shell?", ["Lücke in einer Java-Logging-Bibliothek", "Ein Linux-Befehl", "Ein Cloud-Ausfall", "Ein Git-Fehler"], "Ende 2021, enorm verbreitet."),
   mc("Was beschreibt SLSA?", ["Stufen der Lieferkettensicherheit", "Eine Programmiersprache", "Ein SLO-Ziel", "Ein Container-Format"], "Supply-chain Levels for Software Artifacts."),
   mc("Welche Formate gibt es für SBOMs?", ["SPDX und CycloneDX", "JPEG und PNG", "MP3 und WAV", "DOCX und PDF"], "Maschinenlesbare Standards.")]),
 L("devops.m8.l3", "DevOps für Steuergeräte", 7, [
  "Lassen sich DevOps-Prinzipien auf eingebettete, sicherheitsrelevante Fahrzeugsoftware übertragen? Ja, mit Anpassungen.",
  "## Besonderheiten",
  "Software läuft auf spezieller Hardware, Tests brauchen Prüfstände, Normen wie ISO 26262 und Automotive SPICE verlangen Nachweise, und Auslieferung ins Feld ist seltener und streng reguliert (UN R156). „Täglich in Produktion“ heißt hier: täglich ein potenziell freigabefähiger, geprüfter Stand.",
  "## Die Pipeline im Fahrzeugumfeld",
  "Build mit qualifizierten Compilern, statische Analyse (etwa MISRA), Unit-Tests auf dem Host, Software-in-the-Loop mit virtuellen Steuergeräten, Hardware-in-the-Loop-Prüfstände als Pipeline-Stufen, automatisch erzeugte Nachweise (Rückverfolgbarkeit von Anforderungen zu Tests).",
  "## Was es bringt",
  "Schnelleres Feedback statt Fehler erst im Integrationstest nach Wochen, reproduzierbare Stände, automatisch erzeugte Dokumentation für Audits und eine Grundlage für sichere OTA-Updates.",
  "## Herausforderungen",
  "Knappe Prüfstände, lange HiL-Laufzeiten, Werkzeugqualifizierung, Zusammenarbeit über Hersteller und Zulieferer hinweg und eine Kultur, die von langen Releasezyklen geprägt ist. Erfahrungen und Reifegrad unterscheiden sich stark zwischen Unternehmen."],
  ["Prinzipien gelten, aber mit Prüfständen, Normen und Regulierung.", "Pipeline: qualifizierter Build, MISRA, Unit, SiL, HiL, Rückverfolgbarkeit.", "Nutzen: schnelles Feedback, reproduzierbar, Audit-Nachweise; Hürden: Prüfstände, Kultur."],
  [S_ASPICE, S_26262, S_R156],
  [card("Automotive SPICE", "Prozessbewertungsmodell für Software-Entwicklung im Automobilbereich."), card("Rückverfolgbarkeit", "Nachweisbare Verbindung von Anforderungen über Code zu Tests."), card("Werkzeugqualifizierung", "Nachweis, dass ein Werkzeug für sicherheitsrelevante Entwicklung geeignet ist.")],
  [mc("Was bedeutet „häufig ausliefern“ bei Steuergeräten realistisch?", ["Häufig einen geprüften, freigabefähigen Stand haben", "Täglich OTA an alle Fahrzeuge", "Gar nichts", "Nur jährlich bauen"], "Feldauslieferung bleibt reguliert."),
   mc("Was ist ein typischer Engpass?", ["Knappe HiL-Prüfstände", "Zu viele Prüfstände", "Zu schnelle Compiler", "Fehlende Fahrzeuge"], "Prüfstände sind teuer und belegt."),
   multi("Welche Stufen passen in eine Steuergeräte-Pipeline?", ["Statische Analyse (MISRA)", "Software-in-the-Loop", "Hardware-in-the-Loop", "Manuelles Kopieren per USB"], [0, 1, 2], "Manuelles Kopieren widerspricht der Automatisierung."),
   mc("Was erzeugt eine gute Pipeline zusätzlich für Audits?", ["Nachweise wie Rückverfolgbarkeit", "Werbematerial", "Urlaubspläne", "Nichts"], "Automatisch statt per Hand."),
   mc("Welche Regelung betrifft Updates im Feld?", ["UN R156", "Euro 7", "SAE J1962", "ISO 15765"], "Software-Update-Management.")])
])

